SELECT

FROM mg_course_record_student crs
LEFT JOIN mg_student s ON crs.student_id = s.id AND s.is_deleted = 0
LEFT JOIN sys_user su ON s.sys_user_id = su.id AND su.is_deleted = 0
WHERE 1=1

    AND crs.record_id = #{recordId}


    AND crs.student_id = #{studentId}


    AND crs.course_id = #{courseId}


    AND crs.seat_status = #{seatStatus}


    AND crs.attendance_status = #{attendanceStatus}

ORDER BY crs.seat_index ASC

SELECT

FROM mg_course_record_student crs
LEFT JOIN mg_student s ON crs.student_id = s.id AND s.is_deleted = 0
LEFT JOIN sys_user su ON s.sys_user_id = su.id AND su.is_deleted = 0
WHERE crs.record_id = #{recordId}
AND crs.student_id = #{studentId}

SELECT COUNT(*)
FROM mg_course_record_student
WHERE record_id = #{recordId}
AND seat_index = #{seatIndex}

SELECT COUNT(DISTINCT student_id)
FROM mg_course_record_student
WHERE record_id = #{recordId}
